SELECT TblCase.CaseID, TblCase.Last_Name, TblCase.First_Name, TblCase.Address, TblCase.City, TblCase.State, TblCase.Zip, TblCase.HmPhone, TblCase.OtherPhone, TblCase.Closed, TblCase.Clsdate, TblCase.Referral, TblCase.Email, TblCase.DOB, TblCase.SSN, TblCase.Comments, qryClosingRPT.CaseNo, qryClosingRPT.Disposition, qryClosingRPT.[PI Settlement Amount], qryClosingRPT.Dispo_Date, qryClosingRPT.Dispo_Atty, qryClosingRPT.DispoJudge, qryClosingRPT.DispoOppC, qryClosingRPT.Date2, qryClosingRPT.Pay_Outlay, qryClosingRPT.Charge, qryClosingRPT.Payment, qryClosingRPT.TDate, qryClosingRPT.TMatter, qryClosingRPT.Debit, qryClosingRPT.Credit, qryClosingRPT.Matter_type, qryClosingRPT.CaseOpenDate, qryClosingRPT.Court, qryClosingRPT.Retainer
FROM TblCase INNER JOIN qryClosingRPT ON TblCase.CaseID = qryClosingRPT.CaseID;